import{c as i,Z as o,Q as l,j as r,g as e,n,o as d,m as s}from"./chunks/framework.BPKcPtvA.js";const _=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"title":"Changelog","outline":"deep"},"headers":[],"relativePath":"changelog/changelog.md","filePath":"changelog/changelog.md"}'),u={name:"changelog/changelog.md"},p={id:"changelog-v-1-03",tabindex:"-1"};function h(c,a,m,k,b,g){const t=o("Badge");return l(),r("div",null,[e("h1",p,[a[0]||(a[0]=n("Changelog V_1.03 ",-1)),d(t,{type:"tip",text:"Production"}),a[1]||(a[1]=n()),a[2]||(a[2]=e("a",{class:"header-anchor",href:"#changelog-v-1-03","aria-label":'Permalink to "Changelog V_1.03 <Badge type="tip" text="Production" />"'},"​",-1))]),a[3]||(a[3]=s('<h2 id="fungsi-input-data-di-halaman" tabindex="-1">fungsi input data di halaman <a class="header-anchor" href="#fungsi-input-data-di-halaman" aria-label="Permalink to &quot;fungsi input data di halaman&quot;">​</a></h2><ul><li><p>$nik_admin = $_POST[&#39;nik_admin&#39;]; tapi nama kolom di DB Mysql adalah nik_admin, karena scriptnya sudah berubah seharusnya diganti ke &#39;id_admin&#39;</p></li><li><p>tolong ubah nama kolom di Mysql menjadi &#39;id_admin&#39; di aplikasi versi 0.02</p></li></ul><h2 id="menambahkan-satu-kolom-baru-di-halaman-sales-cost-yaitu-ketika-jenis-kendaraan-hb-then-muncul-kolom-baru-container-size" tabindex="-1">Menambahkan satu kolom baru di Halaman Sales Cost, yaitu Ketika Jenis Kendaraan = HB then muncul kolom baru Container Size <a class="header-anchor" href="#menambahkan-satu-kolom-baru-di-halaman-sales-cost-yaitu-ketika-jenis-kendaraan-hb-then-muncul-kolom-baru-container-size" aria-label="Permalink to &quot;Menambahkan satu kolom baru di Halaman Sales Cost, yaitu Ketika Jenis Kendaraan = HB then muncul kolom baru Container Size&quot;">​</a></h2><ul><li>Menambahkan satu kolom baru di Database &#39;trucking/sales_cost&#39;</li><li>Masuk ke &#39;Structure&#39; &gt; Add &#39;1&#39; column(s) &#39;after jenis_trip&#39; / GO</li><li>Name = &#39;container_size&#39; &gt; Type = &#39;VARCHAR&#39; &gt; Length/Values = &#39;20&#39; &gt; Default = &#39;None&#39; &gt; Null = &#39;Checked&#39; &gt; Save</li></ul><p><br><br></p><h1 id="migrasi-ke-node-js-dan-vue-js-db-phpmyadmin-jadi-masih-dibutuhkan-running-fitur-mysql-di-xampp" tabindex="-1">Migrasi ke Node.JS dan Vue.JS, DB (phpMyAdmin) jadi masih dibutuhkan running fitur MySQL di XAMPP <a class="header-anchor" href="#migrasi-ke-node-js-dan-vue-js-db-phpmyadmin-jadi-masih-dibutuhkan-running-fitur-mysql-di-xampp" aria-label="Permalink to &quot;Migrasi ke Node.JS dan Vue.JS, DB (phpMyAdmin) jadi masih dibutuhkan running fitur MySQL di XAMPP&quot;">​</a></h1><h2 id="running-node-js-dan-vue-js-di-local" tabindex="-1">Running Node. JS dan Vue.JS di Local <a class="header-anchor" href="#running-node-js-dan-vue-js-di-local" aria-label="Permalink to &quot;Running Node. JS dan Vue.JS di Local&quot;">​</a></h2><ul><li>cd c:\\xampp\\htdocs\\transport_v1.03\\tailadmin-vuejs-1.0.0</li></ul><blockquote><p>npm run dev</p></blockquote><ul><li>cd C:\\xampp\\htdocs\\transport_v1.03\\node_backend</li></ul><blockquote><p>npm start</p></blockquote><h2 id="install-mongodb-windows-11" tabindex="-1">Install Mongodb Windows 11 <a class="header-anchor" href="#install-mongodb-windows-11" aria-label="Permalink to &quot;Install Mongodb Windows 11&quot;">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=rCGpx_qb1y0" target="_blank" rel="noreferrer">Youtube Tutorial.</a></li></ul><h2 id="install-mongodb-at-node-backend" tabindex="-1">Install Mongodb at Node Backend <a class="header-anchor" href="#install-mongodb-at-node-backend" aria-label="Permalink to &quot;Install Mongodb at Node Backend&quot;">​</a></h2><p>C:\\xampp\\htdocs\\transport_v1.03\\node_backend</p><blockquote><p>npm list mongoose <br> npm install mongoose</p></blockquote><h2 id="pastikan-ubah-alamat-ip-host-di-front-end-folder-c-xampp-htdocs-transport-v1-03-tailadmin-vuejs-1-0-0" tabindex="-1">Pastikan ubah alamat IP Host di Front End folder : C:\\xampp\\htdocs\\transport_v1.03\\tailadmin-vuejs-1.0.0 <a class="header-anchor" href="#pastikan-ubah-alamat-ip-host-di-front-end-folder-c-xampp-htdocs-transport-v1-03-tailadmin-vuejs-1-0-0" aria-label="Permalink to &quot;Pastikan ubah alamat IP Host di Front End folder : C:\\xampp\\htdocs\\transport_v1.03\\tailadmin-vuejs-1.0.0&quot;">​</a></h2><ul><li>.env.local (*pastikan type &#39;LOCAL File&#39;)</li><li>VITE_API_URL=<a href="http://192.168.60.29:3000" target="_blank" rel="noreferrer">http://192.168.60.29:3000</a> (ganti host 192.168... dengan IP Host Server)</li></ul><h2 id="untuk-running-baru-di-production-host-server" tabindex="-1">untuk running baru di Production (Host Server) <a class="header-anchor" href="#untuk-running-baru-di-production-host-server" aria-label="Permalink to &quot;untuk running baru di Production (Host Server)&quot;">​</a></h2><ul><li>cd c:\\xampp\\htdocs\\transport_v1.03\\tailadmin-vuejs-1.0.0</li></ul><blockquote><p>npm run dev -- --host 0.0.0.0</p></blockquote><h2 id="halaman-repair-ubah-ke-db-trucking-repair-kolom-pada-table" tabindex="-1">Halaman Repair, ubah ke DB trucking.repair kolom pada table : <a class="header-anchor" href="#halaman-repair-ubah-ke-db-trucking-repair-kolom-pada-table" aria-label="Permalink to &quot;Halaman Repair, ubah ke DB trucking.repair kolom pada table :&quot;">​</a></h2><ul><li>MODIFY tgl_kerusakan DATE NULL;</li><li>MODIFY jadwal_berkala DATE NULL;</li></ul><h2 id="jalankan-vitepress-di" tabindex="-1">Jalankan Vitepress di <a class="header-anchor" href="#jalankan-vitepress-di" aria-label="Permalink to &quot;Jalankan Vitepress di&quot;">​</a></h2><p>cd C:\\xampp\\htdocs\\transport_v1.03\\docs</p><ul><li>Localhost</li></ul><blockquote><p>npm run dev</p></blockquote><ul><li>Network in Local</li></ul><blockquote><p>npm run dev -- --host 0.0.0.0</p></blockquote><h2 id="ganti-script-lastupdated-di-c-xampp-htdocs-transport-v1-03-docs-vitepress" tabindex="-1">ganti script &#39;lastUpdated:&#39; di C:\\xampp\\htdocs\\transport_v1.03\\docs.vitepress <a class="header-anchor" href="#ganti-script-lastupdated-di-c-xampp-htdocs-transport-v1-03-docs-vitepress" aria-label="Permalink to &quot;ganti script &#39;lastUpdated:&#39; di C:\\xampp\\htdocs\\transport_v1.03\\docs\\.vitepress&quot;">​</a></h2><p>ubah dari &#39;true&#39; menjadi &#39;false&#39;</p><h2 id="ubah-policy-powershell-ke-administrator" tabindex="-1">Ubah policy powershell ke Administrator <a class="header-anchor" href="#ubah-policy-powershell-ke-administrator" aria-label="Permalink to &quot;Ubah policy powershell ke Administrator&quot;">​</a></h2><blockquote><p>Set-ExecutionPolicy -Scope CurrentUser -ExecutionPolicy RemoteSigned</p></blockquote>',33))])}const q=i(u,[["render",h]]);export{_ as __pageData,q as default};
